function kmpFailure(pattern){
  var n=pattern.length, fail=new Array(n).fill(0);
  var k=0;
  for(var i=1;i<n;i++){
    while(k>0 && pattern[i]!==pattern[k]) k=fail[k-1];
    if(pattern[i]===pattern[k]) k++;
    fail[i]=k;
  }
  return fail;
}
function kmpSearch(text, pattern){
  if(pattern.length===0) return [];
  var fail=kmpFailure(pattern), out=[], k=0;
  for(var i=0;i<text.length;i++){
    while(k>0 && text[i]!==pattern[k]) k=fail[k-1];
    if(text[i]===pattern[k]) k++;
    if(k===pattern.length){ out.push(i-k+1); k=fail[k-1]; }
  }
  return out;
}
function kmpCount(text, pattern){ return kmpSearch(text, pattern).length; }
function kmpFirst(text, pattern){
  var r=kmpSearch(text, pattern);
  return r.length?r[0]:-1;
}
function kmpHighlight(text, pattern){
  var hits=kmpSearch(text, pattern);
  if(!hits.length) return text;
  var out='', last=0;
  for(var i=0;i<hits.length;i++){
    var p=hits[i];
    if(p<last) continue;
    out+=text.slice(last,p)+'\u3010'+text.slice(p,p+pattern.length)+'\u3011';
    last=p+pattern.length;
  }
  return out+text.slice(last);
}
